func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/admin/api-keys", wrapper.ListAPIKeys)
	router.POST(options.BaseURL+"/admin/api-keys", wrapper.CreateAPIKey)
	router.DELETE(options.BaseURL+"/admin/api-keys/:name", wrapper.DeleteAPIKey)
	router.POST(options.BaseURL+"/admin/api-keys/:name/promote", wrapper.PromoteAPIKey)
	router.GET(options.BaseURL+"/admin/namespaces", wrapper.ListNamespaces)
	router.GET(options.BaseURL+"/admin/sandbox-templates", wrapper.AdminListSandboxTemplates)
	router.POST(options.BaseURL+"/admin/sandbox-templates", wrapper.AdminCreateSandboxTemplate)
	router.DELETE(options.BaseURL+"/admin/sandbox-templates/:name", wrapper.AdminDeleteSandboxTemplate)
	router.PUT(options.BaseURL+"/admin/sandbox-templates/:name", wrapper.AdminUpdateSandboxTemplate)
	router.GET(options.BaseURL+"/admin/statistics/sandboxes", wrapper.AdminGetSandboxStatistics)
	router.GET(options.BaseURL+"/admin/teams", wrapper.ListTeams)
	router.GET(options.BaseURL+"/admin/teams/:team/users", wrapper.ListUsersByTeam)
	router.GET(options.BaseURL+"/api-keys", wrapper.SelfListAPIKeys)
	router.POST(options.BaseURL+"/api-keys", wrapper.SelfCreateAPIKey)
	router.DELETE(options.BaseURL+"/api-keys/:name", wrapper.SelfDeleteAPIKey)
	router.GET(options.BaseURL+"/auth/whoami", wrapper.GetWhoAmI)
	router.GET(options.BaseURL+"/clusters", wrapper.ListClusters)
	router.GET(options.BaseURL+"/envs", wrapper.ListSandboxEnvs)
	router.POST(options.BaseURL+"/envs", wrapper.CreateSandboxEnv)
	router.DELETE(options.BaseURL+"/envs/:name", wrapper.DeleteSandboxEnv)
	router.GET(options.BaseURL+"/envs/:name", wrapper.GetSandboxEnv)
	router.PATCH(options.BaseURL+"/envs/:name", wrapper.UpdateSandboxEnv)
	router.GET(options.BaseURL+"/envs/:name/sandboxpools", wrapper.ListEnvSandboxPools)
	router.POST(options.BaseURL+"/envs/:name/sandboxpools", wrapper.CreateEnvSandboxPool)
	router.DELETE(options.BaseURL+"/envs/:name/sandboxpools/:poolName", wrapper.DeleteEnvSandboxPool)
	router.GET(options.BaseURL+"/envs/:name/sandboxpools/:poolName", wrapper.GetEnvSandboxPool)
	router.PUT(options.BaseURL+"/envs/:name/sandboxpools/:poolName", wrapper.UpdateEnvSandboxPool)
	router.POST(options.BaseURL+"/envs/:name/sync-template", wrapper.SyncSandboxEnvTemplate)
	router.GET(options.BaseURL+"/feature-gates", wrapper.GetFeatureGates)
	router.GET(options.BaseURL+"/instancetypes", wrapper.ListInstanceTypes)
	router.GET(options.BaseURL+"/quotas", wrapper.ListQuotas)
	router.GET(options.BaseURL+"/sandbox-templates", wrapper.ListSandboxTemplates)
	router.GET(options.BaseURL+"/sandbox-templates/:name", wrapper.GetSandboxTemplate)
	router.GET(options.BaseURL+"/sandboxes", wrapper.ListSandboxes)
	router.POST(options.BaseURL+"/sandboxes", wrapper.CreateSandbox)
	router.DELETE(options.BaseURL+"/sandboxes/:sandboxId", wrapper.DeleteSandbox)
	router.GET(options.BaseURL+"/sandboxes/:sandboxId", wrapper.GetSandbox)
	router.POST(options.BaseURL+"/sandboxes/:sandboxId/exec", wrapper.ExecSandboxCommand)
	router.POST(options.BaseURL+"/sandboxes/:sandboxId/exec-token", wrapper.CreateSandboxExecToken)
	router.GET(options.BaseURL+"/sandboxes/:sandboxId/is_ready", wrapper.IsSandboxReady)
	router.GET(options.BaseURL+"/sandboxes/:sandboxId/logs", wrapper.GetSandboxLogs)
	router.PUT(options.BaseURL+"/sandboxes/:sandboxId/timeout", wrapper.SetSandboxTimeout)
	router.GET(options.BaseURL+"/statistics/sandboxes", wrapper.GetUserSandboxStatistics)
}

